const r = $json;

// ---------------------------------------------------------
// Contexto da iteração atual
// ---------------------------------------------------------

const origem = $('Loop').item.json;


// ---------------------------------------------------------
// Resposta do registro da mídia virtual
// ---------------------------------------------------------

const virtualResp =
  $('Registrar Mídia Virtual WP vs0.2').item.json;

const virtualBody =
  virtualResp?.body &&
  typeof virtualResp.body === 'object'
    ? virtualResp.body
    : virtualResp;


// ---------------------------------------------------------
// Identificadores principais
// ---------------------------------------------------------

const migrationId = Number(
  r.migration_id ??
  origem.migration_id
);

const postIdEsperado = Number(
  r.post_id ??
  origem.post_id
);

const mediaOriginal = Number(
  r.wp_media_id_original ??
  origem.wp_media_id_original
);


// ---------------------------------------------------------
// Attachment virtual esperado
// ---------------------------------------------------------

const attachmentIdEsperado = Number(
  r.wp_media_id_virtual ??
  r.external_attachment_id ??
  r.attachment_id ??
  virtualBody?.attachment_id
);


// ---------------------------------------------------------
// Valores retornados pelo /assign
// ---------------------------------------------------------

const postIdRecebido =
  Number(r.post_id);

const attachmentIdRecebido =
  Number(r.attachment_id);

const featuredMediaRecebido =
  Number(r.featured_media);


// ---------------------------------------------------------
// Validação estrutural
// ---------------------------------------------------------

if (!migrationId) {
  throw new Error(
    'migration_id inválido na validação da associação WP'
  );
}

if (!postIdEsperado) {
  throw new Error(
    `Migration ${migrationId}: post_id esperado inválido`
  );
}

if (!mediaOriginal) {
  throw new Error(
    `Migration ${migrationId}: wp_media_id_original inválido`
  );
}

if (!attachmentIdEsperado) {
  throw new Error(
    `Migration ${migrationId}: attachment virtual esperado não encontrado`
  );
}


// ---------------------------------------------------------
// Validação funcional
// ---------------------------------------------------------

const checks = {

  post_ok:
    postIdRecebido === postIdEsperado,

  attachment_ok:
    attachmentIdRecebido === attachmentIdEsperado,

  featured_ok:
    featuredMediaRecebido === attachmentIdEsperado

};

const valido =
  Object.values(checks)
    .every(v => v === true);


if (!valido) {

  throw new Error(
    `Falha associação WP | ` +
    `migration=${migrationId} | ` +
    `post esperado=${postIdEsperado} recebido=${postIdRecebido} | ` +
    `attachment esperado=${attachmentIdEsperado} recebido=${attachmentIdRecebido} | ` +
    `featured esperado=${attachmentIdEsperado} recebido=${featuredMediaRecebido}`
  );

}


// ---------------------------------------------------------
// URL CANÔNICA DA MIGRATION
//
// IMPORTANTE:
// secure_url do WordPress NÃO participa deste campo.
// ---------------------------------------------------------

const cloudinaryUrl =
  origem.cloudinary_url ??
  r.cloudinary_url ??
  null;

if (!cloudinaryUrl) {
  throw new Error(
    `Migration ${migrationId}: cloudinary_url canônica não encontrada`
  );
}


// ---------------------------------------------------------
// URL EFETIVAMENTE UTILIZADA PELO ATTACHMENT VIRTUAL
//
// Pode ser uma URL reutilizada de migration anterior.
// ---------------------------------------------------------

const mediaVirtualUrl =
  r.media_virtual_url ??
  r.secure_url ??
  virtualBody?.secure_url ??
  null;


// ---------------------------------------------------------
// Associação validada
// ---------------------------------------------------------

return [{
  json: {

    migration_id:
      migrationId,

    post_id:
      postIdEsperado,

    wp_media_id_original:
      mediaOriginal,

    wp_media_id_virtual:
      attachmentIdEsperado,

    featured_media:
      featuredMediaRecebido,

    cloudinary_url:
      cloudinaryUrl,

    media_virtual_url:
      mediaVirtualUrl,

    wp_associado:
      true,

    wp_validado:
      true,

    associacao_wp_confirmada:
      true,

    wp_meta_updated:
      r.native_attachment_meta_updated === true

  }
}];

// =========================================================
// 1. RECUPERA MIGRATIONS CONCLUÍDAS PELO NOVO FILHO 2
// =========================================================

const retornoExclusao =
  $('Chamar | Exclusão e Auditoria').all();

const migrados = [];

// O subfluxo pode retornar:
// - um resultset como array
// - objetos individuais
// - metadata estrutural do MySQL
for (const item of retornoExclusao) {

  const value = item.json;

  // ResultSet MySQL
  if (Array.isArray(value)) {

    for (const registro of value) {

      if (
        registro?.migration_id &&
        registro?.status === 'MIGRATED'
      ) {
        migrados.push(registro);
      }

    }

    continue;
  }

  // Objeto funcional direto
  if (
    value?.migration_id &&
    value?.status === 'MIGRATED'
  ) {
    migrados.push(value);
  }
}


// =========================================================
// 2. REMOVE EVENTUAIS DUPLICIDADES
// =========================================================

const mapaMigrados = new Map();

for (const item of migrados) {
  mapaMigrados.set(
    Number(item.migration_id),
    item
  );
}

const loteConcluido =
  [...mapaMigrados.values()];


// =========================================================
// 3. VALIDA LOTE CONCLUÍDO
// =========================================================

if (loteConcluido.length === 0) {
  throw new Error(
    'Nenhuma migration MIGRATED retornada pelo subfluxo de Exclusão e Auditoria.'
  );
}


// =========================================================
// 4. RECUPERA RESULTADO DO CHECKPOINT
// =========================================================

const checkpointRaw = $input.all();

let checkpoint = null;

for (const item of checkpointRaw) {

  const value = item.json;

  // ResultSet retornado pela SP
  if (Array.isArray(value)) {

    const encontrado =
      value.find(x => x?.resultado);

    if (encontrado) {
      checkpoint = encontrado;
      break;
    }
  }

  // Compatibilidade com retorno direto
  if (value?.resultado) {
    checkpoint = value;
    break;
  }
}


// =========================================================
// 5. NORMALIZA POSTS MIGRADOS
// =========================================================

const posts = loteConcluido.map(item => {

  const postId =
    Number(item.post_id);

  return {

    migration_id:
      Number(item.migration_id),

    post_id:
      postId,

    url_publica:
      `https://energialimpa.live/?p=${postId}`,

    wp_media_id_original:
      Number(item.wp_media_id_original),

    wp_media_id_virtual:
      Number(item.wp_media_id_virtual),

    cloudinary_url:
      item.cloudinary_url
  };
});


// =========================================================
// 6. HTML DOS POSTS
// =========================================================

const listaHtml = posts
  .map(post => `
    <div style="margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid #ddd;">
      <strong>Post ID:</strong> ${post.post_id}<br>

      <strong>Migration ID:</strong> ${post.migration_id}<br>

      <strong>URL:</strong>
      <a
        href="${post.url_publica}"
        target="_blank"
      >
        ${post.url_publica}
      </a>
    </div>
  `)
  .join('');


// =========================================================
// 7. CHECKPOINT
// =========================================================

const statusCheckpoint =
  checkpoint?.resultado ??
  'NÃO INFORMADO';

const totalResolvidos =
  checkpoint?.total_resolvidos ??
  '-';

const totalCandidatos =
  checkpoint?.total_candidatos ??
  '-';

const paginaAtual =
  checkpoint?.pagina_atual ??
  '-';


// =========================================================
// 8. SAÍDA PARA GMAIL
// =========================================================

return [
  {
    json: {

      assunto:
        `Migração Featured concluída | ${posts.length} posts`,

      total_migrados_lote:
        posts.length,

      checkpoint_status:
        statusCheckpoint,

      total_resolvidos:
        totalResolvidos,

      total_candidatos:
        totalCandidatos,

      pagina_atual:
        paginaAtual,

      posts,

      html: `
        <h2>Migração Featured concluída</h2>

        <p>
          <strong>Migrados nesta execução:</strong>
          ${posts.length}<br>

          <strong>Checkpoint:</strong>
          ${statusCheckpoint}<br>

          <strong>Resolvidos:</strong>
          ${totalResolvidos}/${totalCandidatos}<br>

          <strong>Página atual:</strong>
          ${paginaAtual}
        </p>

        <h3>Posts para conferência visual</h3>

        ${listaHtml}
      `
    }
  }
];

const itens = $input.all();

// O Loop trabalha com 1 mídia por vez.
// Recupera o payload usado antes do POST de associação.
const ctx = $('Wait 60').item.json;

return itens.map(item => {
  const resp = item.json;

  const statusCode = Number(
    resp.statusCode ?? 0
  );

  const body = resp.body ?? {};

  const originStatus = Number(
    body?.origin_status ??
    statusCode ??
    0
  );

  // ---------------------------------------------------------
  // Texto consolidado para identificar respostas de erro
  // ---------------------------------------------------------

  const textoErro = [
    typeof body === 'string'
      ? body
      : '',

    body?.origin_body ?? '',
    body?.message ?? '',
    body?.error ?? ''
  ]
    .filter(Boolean)
    .join(' ');

  // ---------------------------------------------------------
  // Classificação da resposta
  // ---------------------------------------------------------

  let resultado = 'ERRO_REAL';

  // Sucesso HTTP
  if (
    statusCode >= 200 &&
    statusCode < 300
  ) {
    resultado = 'SUCESSO';
  }

  // WAF / proteção Hostinger
  else if (
    statusCode === 403 &&
    (
      originStatus === 403 ||
      textoErro.includes('Checking your browser') ||
      textoErro.includes('Just a moment')
    )
  ) {
    resultado = 'WAF_403';
  }

  // Rate limit
  else if (
    statusCode === 429 ||
    originStatus === 429
  ) {
    resultado = 'RATE_LIMIT_429';
  }

  // ---------------------------------------------------------
  // Normaliza body quando for objeto
  // ---------------------------------------------------------

  const bodyNormalizado =
    body &&
    typeof body === 'object' &&
    !Array.isArray(body)
      ? body
      : {};

  // ---------------------------------------------------------
  // Saída
  // ---------------------------------------------------------

  return {
    json: {
      // Preserva TODO o contexto original da migration.
      // Isso será fundamental para recuperação e retry.
      ...ctx,

      // Preserva também a resposta original do endpoint.
      ...bodyNormalizado,

      // -----------------------------------------------------
      // Identificadores normalizados
      // -----------------------------------------------------

      migration_id: Number(
        ctx.migration_id ??
        bodyNormalizado.migration_id
      ),

      post_id: Number(
        ctx.post_id ??
        bodyNormalizado.post_id
      ),

      wp_media_id_original: Number(
        ctx.wp_media_id_original ??
        bodyNormalizado.wp_media_id_original
      ),

      wp_media_id_virtual: Number(
        ctx.external_attachment_id ??
        ctx.wp_media_id_virtual ??
        bodyNormalizado.attachment_id ??
        bodyNormalizado.wp_media_id_virtual
      ),

      cloudinary_url:
        ctx.cloudinary_url ??
        bodyNormalizado.secure_url ??
        null,

      // -----------------------------------------------------
      // Controle técnico
      // -----------------------------------------------------

      resultado_associacao: resultado,

      http_status:
        statusCode,

      origin_status:
        originStatus || null,

      erro_resumo:
        textoErro || null,

      // -----------------------------------------------------
      // Auditoria
      // -----------------------------------------------------

      response_headers:
        resp.headers ?? {}
    }
  };
});

const respostas = $input.all();
const contextos = $('Wait | Recuperação WP').all();

if (respostas.length !== contextos.length) {
  throw new Error(
    `Quantidade incompatível: ${respostas.length} respostas ` +
    `para ${contextos.length} contextos de recuperação`
  );
}

return respostas.map((item, index) => {
  const resp = item.json;
  const ctx = contextos[index].json;

  const statusCode = Number(resp.statusCode ?? 0);
  const body = resp.body ?? {};

  const originStatus = Number(
    body?.origin_status ??
    statusCode ??
    0
  );

  const postId = Number(
    body?.id ??
    ctx.post_id
  );

  const featuredAtual = Number(
    body?.featured_media ?? 0
  );

  const featuredEsperado = Number(
    ctx.wp_media_id_virtual
  );

  let resultado = 'ERRO_VALIDACAO';

  // GET funcionou e a associação realmente existe
  if (
    statusCode === 200 &&
    postId === Number(ctx.post_id) &&
    featuredAtual === featuredEsperado
  ) {
    resultado = 'ASSOCIADO';
  }

  // GET funcionou, mas o post ainda não aponta para a virtual
  else if (statusCode === 200) {
    resultado = 'NAO_ASSOCIADO';
  }

  // O próprio GET também sofreu bloqueio transitório
  else if (
    statusCode === 403 ||
    originStatus === 403 ||
    statusCode === 429 ||
    originStatus === 429
  ) {
    resultado = 'BLOQUEIO_PERSISTENTE';
  }

  return {
    json: {
      // Preserva todo o contexto anterior para eventual retry
      ...ctx,

      post_id: Number(ctx.post_id),
      wp_media_id_original: Number(ctx.wp_media_id_original),
      wp_media_id_virtual: featuredEsperado,

      featured_media_atual: featuredAtual || null,

      resultado_pos_erro: resultado,

      http_status_validacao: statusCode,
      origin_status_validacao: originStatus || null,

      associacao_confirmada:
        resultado === 'ASSOCIADO'
    }
  };
});

const itens = $input.all();

// Contexto que chegou ao Retry
const ctx = $('Roteia | Pós-Erro Associação').item.json;

return itens.map(item => {
  const resp = item.json;

  const statusCode = Number(resp.statusCode ?? 0);
  const body = resp.body ?? {};

  const originStatus = Number(
    body?.origin_status ??
    statusCode ??
    0
  );

  const textoErro = [
    typeof body === 'string' ? body : '',
    body?.origin_body ?? '',
    body?.message ?? '',
    body?.error ?? ''
  ]
    .filter(Boolean)
    .join(' ');

  const bodyNormalizado =
    body &&
    typeof body === 'object' &&
    !Array.isArray(body)
      ? body
      : {};

  const sucesso =
    statusCode >= 200 &&
    statusCode < 300;

  return {
    json: {
      // Mantém contexto da migration
      ...ctx,

      // Mantém a resposta funcional do POST
      ...bodyNormalizado,

      migration_id: Number(
        ctx.migration_id ??
        bodyNormalizado.migration_id
      ),

      post_id: Number(
        ctx.post_id ??
        bodyNormalizado.post_id
      ),

      wp_media_id_original: Number(
        ctx.wp_media_id_original ??
        bodyNormalizado.wp_media_id_original
      ),

      wp_media_id_virtual: Number(
        ctx.wp_media_id_virtual ??
        bodyNormalizado.attachment_id ??
        bodyNormalizado.wp_media_id_virtual
      ),

      cloudinary_url:
        ctx.cloudinary_url ??
        bodyNormalizado.secure_url ??
        null,

      resultado_retry:
        sucesso
          ? 'SUCESSO_FINAL'
          : 'FALHA_FINAL',

      http_status_retry: statusCode,

      origin_status_retry:
        originStatus || null,

      erro_retry:
        textoErro || null,

      response_headers_retry:
        resp.headers ?? {}
    }
  };
});

const itens = $input.all();

return itens.map(item => {
  const x = item.json;

  const migrationId = Number(x.migration_id);
  const postId = Number(x.post_id);

  const originalId = Number(
    x.wp_media_id_original ?? 0
  );

  const virtualId = Number(
    x.wp_media_id_virtual ??
    x.external_attachment_id ??
    x.attachment_id ??
    0
  );

  if (!migrationId || !postId || !originalId) {
    throw new Error(
      `Contexto incompleto para registrar falha. ` +
      `migration=${x.migration_id}, post=${x.post_id}`
    );
  }

  // Identifica de qual ponto do tratamento veio a falha
  const motivo =
    x.resultado_retry ??
    x.resultado_pos_erro ??
    x.resultado_associacao ??
    'ERRO_ASSOCIACAO_WP';

  const httpStatus = Number(
    x.http_status_retry ??
    x.http_status_validacao ??
    x.http_status ??
    0
  ) || null;

  const originStatus = Number(
    x.origin_status_retry ??
    x.origin_status_validacao ??
    x.origin_status ??
    0
  ) || null;

  const detalhe =
    x.erro_retry ??
    x.erro_resumo ??
    null;

  const mensagem = [
    motivo,
    httpStatus ? `HTTP=${httpStatus}` : null,
    originStatus ? `ORIGIN=${originStatus}` : null,
    detalhe
  ]
    .filter(Boolean)
    .join(' | ')
    .slice(0, 1000);

  return {
    json: {
      migration_id: migrationId,
      post_id: postId,
      wp_media_id_original: originalId,

      wp_media_id_virtual:
        virtualId > 0 ? virtualId : null,

      cloudinary_url:
        x.cloudinary_url ?? null,

      status_destino: 'ERROR',

      motivo_erro: motivo,
      http_status: httpStatus,
      origin_status: originStatus,
      error_message: mensagem
    }
  };
});

const itens = $input.all();

return itens.map(item => {

  const x = item.json;

  const migrationId =
    Number(x.migration_id);

  const postId =
    Number(x.post_id);

  const originalId =
    Number(
      x.wp_media_id_original ?? 0
    );

  const virtualId =
    Number(
      x.wp_media_id_virtual ??
      x.attachment_id ??
      x.external_attachment_id ??
      0
    );


  // -------------------------------------------------------
  // URL CANÔNICA
  // Já deve vir preservada do Valida | Associação WP
  // -------------------------------------------------------

  const cloudinaryUrl =
    x.cloudinary_url ??
    null;


  // -------------------------------------------------------
  // URL DO ATTACHMENT VIRTUAL
  // -------------------------------------------------------

  const mediaVirtualUrl =
    x.media_virtual_url ??
    x.secure_url ??
    null;


  // -------------------------------------------------------
  // Validação estrutural
  // -------------------------------------------------------

  if (
    !migrationId ||
    !postId ||
    !originalId ||
    !virtualId
  ) {

    throw new Error(
      `Contexto inválido para associação confirmada. ` +
      `migration=${x.migration_id}, ` +
      `post=${x.post_id}, ` +
      `original=${x.wp_media_id_original}, ` +
      `virtual=${virtualId}`
    );

  }


  if (!cloudinaryUrl) {

    throw new Error(
      `Migration ${migrationId}: ` +
      `cloudinary_url canônica não encontrada`
    );

  }


  return {
    json: {

      ...x,

      migration_id:
        migrationId,

      post_id:
        postId,

      wp_media_id_original:
        originalId,

      wp_media_id_virtual:
        virtualId,

      cloudinary_url:
        cloudinaryUrl,

      media_virtual_url:
        mediaVirtualUrl,

      associacao_wp_confirmada:
        true

    }
  };

});

const origem = $('Loop').item.json;
const retorno = $json;
const resp = retorno.body ?? retorno;

const migrationId = Number(origem.migration_id);
const attachmentId = Number(resp.attachment_id);
const statusCode = Number(retorno.statusCode ?? 0);

if (statusCode && (statusCode < 200 || statusCode >= 300)) {
  throw new Error(
    `Migration ${migrationId}: registro WP retornou HTTP ${statusCode}.`
  );
}

if (!Number.isSafeInteger(attachmentId) || attachmentId <= 0) {
  throw new Error(`Migration ${migrationId}: attachment_id inválido.`);
}

const esperado = {
  sha256: origem.sha256,
  provider: origem.storage_provider,
  public_id: origem.storage_key,
  asset_id: origem.storage_asset_id,
  secure_url: origem.storage_url,
};

for (const [campo, valor] of Object.entries(esperado)) {
  if (!valor || String(resp[campo] ?? '') !== String(valor)) {
    throw new Error(
      `Migration ${migrationId}: ${campo} da mídia virtual difere do storage registrado.`
    );
  }
}

const width = Number(origem.storage_width ?? origem.width);
const height = Number(origem.storage_height ?? origem.height);

if (
  !Number.isSafeInteger(width) ||
  width <= 0 ||
  !Number.isSafeInteger(height) ||
  height <= 0 ||
  Number(resp.width) !== width ||
  Number(resp.height) !== height
) {
  throw new Error(
    `Migration ${migrationId}: dimensões da mídia virtual divergentes.`
  );
}

return [{
  json: {
    ...origem,
    wp_media_id_virtual: attachmentId,
    media_virtual_url: resp.secure_url,
    cloudinary_url:
      esperado.provider === 'cloudinary' ? resp.secure_url : null,
    virtual_existing: Boolean(resp.existing),
    virtual_provider: resp.provider,
    virtual_sha256: resp.sha256,
    virtual_public_id: resp.public_id,
    virtual_asset_id: resp.asset_id,
  },
}];

const r = $json;

const body = (
  r.body &&
  typeof r.body === 'object'
)
  ? r.body
  : {};

const statusCode = Number(
  body.origin_status ??
  r.statusCode ??
  0
);

const attachmentId = Number(
  body.attachment_id ?? 0
);

// Sucesso real
if (
  [200, 201].includes(statusCode) &&
  attachmentId > 0
) {
  return [{
    json: {
      ...r,
      classificacao_registro: 'SUCESSO',
      retry_after: 0
    }
  }];
}

// Tenta extrair retry_after do origin_body
let retryAfter = 120;

if (typeof body.origin_body === 'string') {
  try {
    const parsed = JSON.parse(body.origin_body);

    if (Number(parsed.retry_after) > 0) {
      retryAfter = Number(parsed.retry_after);
    }
  } catch {}
}

// Erros transitórios de infraestrutura/WAF
const transitorios = [
  403,
  429,
  500,
  502,
  503,
  504,
  520,
  522,
  523,
  524
];

if (transitorios.includes(statusCode)) {
  return [{
    json: {
      ...r,
      classificacao_registro: 'TRANSITORIO',
      retry_after: retryAfter,
      http_status: statusCode
    }
  }];
}

// Erro definitivo
return [{
  json: {
    ...r,
    classificacao_registro: 'ERRO_REAL',
    retry_after: 0,
    http_status: statusCode
  }
}];

const r = $json;
const body = r.body ?? {};

const statusCode = Number(
  body.origin_status ??
  r.statusCode ??
  0
);

const attachmentId = Number(
  body.attachment_id ?? 0
);

const sucesso =
  [200, 201].includes(statusCode) &&
  attachmentId > 0;

return [{
  json: {
    ...r,
    classificacao_retry_registro:
      sucesso
        ? 'SUCESSO_FINAL'
        : 'FALHA_FINAL',

    http_status: statusCode
  }
}];

const r = $json;

// Contexto original da migration dentro do Loop1
const origem = $('Loop').item.json;

const body = (
  r.body &&
  typeof r.body === 'object'
)
  ? r.body
  : {};

const httpStatus = Number(
  body.origin_status ??
  r.http_status ??
  r.statusCode ??
  0
);

// Tenta obter mensagem detalhada do origin
let detalhe = '';

if (typeof body.origin_body === 'string') {
  try {
    const parsed = JSON.parse(body.origin_body);

    detalhe =
      parsed.detail ??
      parsed.title ??
      parsed.error_name ??
      body.origin_body;
  } catch {
    detalhe = body.origin_body;
  }
}

if (!detalhe) {
  detalhe =
    body.message ??
    body.error ??
    r.statusMessage ??
    'Falha ao registrar mídia virtual no WordPress';
}

const erro =
  `Falha registro mídia virtual | ` +
  `HTTP ${httpStatus || 'N/A'} | ` +
  detalhe;

return [{
  json: {
    migration_id: Number(origem.migration_id),
    post_id: Number(origem.post_id),
    wp_media_id_original: Number(origem.wp_media_id_original),

    // Pode não existir, porque a falha ocorreu antes da criação
    wp_media_id_virtual: null,

    cloudinary_url:
      origem.cloudinary_url ?? null,

    status_destino: 'ERROR',

    etapa_erro:
      'REGISTRO_MIDIA_VIRTUAL',

    http_status:
      httpStatus || null,

    error_message:
      erro.slice(0, 1000)
  }
}];

const respostas = $input.all();
const contextos = $('Valida | Featured Atual v0.3').all();

const porMidiaVirtual = new Map(
  contextos.map(item => [
    Number(item.json.wp_media_id_virtual),
    item.json
  ])
);

function mesmaMidiaCloudinary(canonica, servida) {
  if (canonica === servida) return true;

  const original = canonica.match(
    /^https:\/\/res\.cloudinary\.com\/([a-z0-9_-]+)\/image\/upload\/(v\d+\/[^?#]+)$/i
  );

  const variante = servida.match(
    /^https:\/\/res\.cloudinary\.com\/([a-z0-9_-]+)\/image\/upload\/c_limit,w_\d+\/(v\d+\/[^?#]+)$/i
  );

  return Boolean(
    original &&
    variante &&
    original[1] === variante[1] &&
    original[2] === variante[2]
  );
}

return respostas.map(item => {
  const media =
    item.json?.body && typeof item.json.body === 'object'
      ? item.json.body
      : item.json;

  const mediaId = Number(media.id);
  const ctx = porMidiaVirtual.get(mediaId);

  if (!ctx) {
    throw new Error(
      `Mídia virtual ${mediaId}: contexto da migração não encontrado.`
    );
  }

  const migrationId = Number(ctx.migration_id);
  const postId = Number(ctx.post_id);
  const originalId = Number(ctx.wp_media_id_original);
  const virtualId = Number(ctx.wp_media_id_virtual);
  const provider = String(ctx.storage_provider ?? '').trim();
  const storageUrl = String(ctx.storage_url ?? '').trim();
  const mediaUrl = String(media.source_url ?? '').trim();

  if (
    !Number.isSafeInteger(migrationId) || migrationId <= 0 ||
    !Number.isSafeInteger(postId) || postId <= 0 ||
    !Number.isSafeInteger(originalId) || originalId <= 0 ||
    !Number.isSafeInteger(virtualId) || virtualId <= 0
  ) {
    throw new Error(
      `Migration ${migrationId}: IDs inválidos na liberação de exclusão.`
    );
  }

  const associacaoConfirmada =
    ctx.associacao_wp_confirmada === true &&
    ctx.associacao_validada === true;

  const idVirtualCorreto = mediaId === virtualId;
  const idsDistintos = originalId !== virtualId;
  const providerValido = /^[a-z0-9_]{1,100}$/.test(provider);

  let urlValida = false;

  if (
    providerValido &&
    /^https:\/\/[^/\s]+\/\S+$/.test(storageUrl) &&
    /^https:\/\/[^/\s]+\/\S+$/.test(mediaUrl)
  ) {
    urlValida = provider === 'cloudinary'
      ? mesmaMidiaCloudinary(storageUrl, mediaUrl)
      : mediaUrl === storageUrl;
  }

  const motivos = [];

  if (!associacaoConfirmada) {
    motivos.push('ASSOCIACAO_WP_NAO_CONFIRMADA');
  }

  if (!idVirtualCorreto) {
    motivos.push('ID_VIRTUAL_DIVERGENTE');
  }

  if (!idsDistintos) {
    motivos.push('ORIGINAL_IGUAL_VIRTUAL');
  }

  if (!providerValido) {
    motivos.push('STORAGE_PROVIDER_INVALIDO');
  }

  if (!urlValida) {
    motivos.push('URL_STORAGE_DIVERGENTE');
  }

  const liberado = motivos.length === 0;

  return {
    json: {
      ...ctx,
      migration_id: migrationId,
      post_id: postId,
      wp_media_id_original: originalId,
      wp_media_id_virtual: virtualId,
      storage_provider: provider,
      storage_url: storageUrl,
      media_virtual_url: mediaUrl,
      associacao_wp_confirmada: associacaoConfirmada,
      exclusao_liberada: liberado,
      motivo_bloqueio: liberado ? null : motivos.join(' | ')
    }
  };
});

const entrada = $('Start WP').all();
const origens = new Map();

for (const item of entrada) {
  const origem = item.json;
  const migrationId = Number(origem.migration_id);

  if (!Number.isSafeInteger(migrationId) || migrationId <= 0) {
    throw new Error('Start WP contém migration_id inválido.');
  }

  if (origens.has(migrationId)) {
    throw new Error(`Migration ${migrationId}: entrada duplicada em Start WP.`);
  }

  origens.set(migrationId, origem);
}

const itensConfirmados = [];

for (let runIndex = 0; runIndex < entrada.length; runIndex++) {
  try {
    const itensRun = $('Normaliza | Associação Confirmada')
      .all(0, runIndex);

    if (Array.isArray(itensRun)) {
      itensConfirmados.push(...itensRun);
    }
  } catch {
    // A iteração pode ter seguido pelo ramo de erro.
  }
}

const mapa = new Map();

for (const item of itensConfirmados) {
  const x = item.json;

  if (x.associacao_wp_confirmada !== true) {
    continue;
  }

  const migrationId = Number(x.migration_id);
  const postId = Number(x.post_id);
  const originalId = Number(x.wp_media_id_original);
  const virtualId = Number(x.wp_media_id_virtual);

  if (
    !Number.isSafeInteger(migrationId) || migrationId <= 0 ||
    !Number.isSafeInteger(postId) || postId <= 0 ||
    !Number.isSafeInteger(originalId) || originalId <= 0 ||
    !Number.isSafeInteger(virtualId) || virtualId <= 0
  ) {
    throw new Error(
      `Contexto inválido na associação | ` +
      `migration=${x.migration_id} | post=${x.post_id} | ` +
      `original=${x.wp_media_id_original} | virtual=${x.wp_media_id_virtual}`
    );
  }

  const origem = origens.get(migrationId);

  if (
    !origem ||
    Number(origem.post_id) !== postId ||
    Number(origem.wp_media_id_original) !== originalId
  ) {
    throw new Error(
      `Migration ${migrationId}: associação difere da entrada de Start WP.`
    );
  }

  const provider = String(origem.storage_provider ?? '').trim();
  const storageUrl = String(origem.storage_url ?? '').trim();

  if (
    !/^[a-z0-9_]{1,100}$/.test(provider) ||
    !/^https:\/\/[^/\s]+\/\S+$/.test(storageUrl)
  ) {
    throw new Error(
      `Migration ${migrationId}: storage canônico ausente ou inválido.`
    );
  }

  if (
    (x.storage_provider != null &&
      String(x.storage_provider) !== provider) ||
    (x.storage_url != null &&
      String(x.storage_url) !== storageUrl)
  ) {
    throw new Error(
      `Migration ${migrationId}: storage da associação divergente.`
    );
  }

  const anterior = mapa.get(migrationId);

  if (anterior && anterior.wp_media_id_virtual !== virtualId) {
    throw new Error(
      `Migration ${migrationId}: mídias virtuais conflitantes.`
    );
  }

  mapa.set(migrationId, {
    migration_id: migrationId,
    post_id: postId,
    wp_media_id_original: originalId,
    wp_media_id_virtual: virtualId,
    storage_provider: provider,
    storage_url: storageUrl,
    associacao_wp_confirmada: true
  });
}

const saida = [...mapa.values()]
  .sort((a, b) => a.migration_id - b.migration_id)
  .map(json => ({
    json: {
      ...json,
      tem_associacao_confirmada: true
    }
  }));

if (saida.length === 0) {
  return [{
    json: {
      tem_associacao_confirmada: false,
      total_associacoes_confirmadas: 0
    }
  }];
}

return saida;

const respostas = $input.all();
const associacoes = $('Recupera | Lote Associação v0.3').all();

const porPost = new Map(
  associacoes.map(item => [
    Number(item.json.post_id),
    item.json
  ])
);

return respostas.map(item => {
  const post =
    item.json?.body && typeof item.json.body === 'object'
      ? item.json.body
      : item.json;

  const postId = Number(post.id);
  const origem = porPost.get(postId);

  if (!origem || origem.associacao_wp_confirmada !== true) {
    throw new Error(
      `Post ${postId}: associação confirmada não encontrada.`
    );
  }

  const migrationId = Number(origem.migration_id);
  const originalId = Number(origem.wp_media_id_original);
  const virtualId = Number(origem.wp_media_id_virtual);
  const featuredAtual = Number(post.featured_media);

  if (
    !Number.isSafeInteger(migrationId) || migrationId <= 0 ||
    !Number.isSafeInteger(originalId) || originalId <= 0 ||
    !Number.isSafeInteger(virtualId) || virtualId <= 0 ||
    featuredAtual !== virtualId ||
    originalId === virtualId
  ) {
    throw new Error(
      `Migration ${migrationId}: featured_media do post ${postId} ` +
      `não corresponde à mídia virtual ${virtualId}.`
    );
  }

  const provider = String(origem.storage_provider ?? '').trim();
  const storageUrl = String(origem.storage_url ?? '').trim();

  if (
    !/^[a-z0-9_]{1,100}$/.test(provider) ||
    !/^https:\/\/[^/\s]+\/\S+$/.test(storageUrl)
  ) {
    throw new Error(
      `Migration ${migrationId}: storage canônico inválido.`
    );
  }

  return {
    json: {
      migration_id: migrationId,
      post_id: postId,
      wp_media_id_original: originalId,
      wp_media_id_virtual: virtualId,
      storage_provider: provider,
      storage_url: storageUrl,
      post_status: post.status ?? null,
      associacao_wp_confirmada: true,
      associacao_validada: true
    }
  };
});
